using CPE_Review_Hub.Models;

namespace CPE_Review_Hub.Services.Curriculum;

/// <summary>
/// Research-linked, course-specific study notes and practice metadata for the
/// proposed first-year sequence. The local department syllabus should be used
/// for final faculty approval before this is treated as the official syllabus.
/// </summary>
public static class Level100StudyGuides
{
    private static readonly CurriculumReference Purdue = new("Unit 1: Introduction to Computing & Digital Literacy", "Purdue University, Department of Computer Science", "https://www.cs.purdue.edu/outreach/indiana-4565-curriculum/unit-1-intro-computing.html", "Computing concepts, algorithms, hardware/software, and digital literacy.");
    private static readonly CurriculumReference Stanford = new("CS101: Introduction to Computing Principles", "Stanford University, Computer Science", "https://web.stanford.edu/class/cs101/", "Introductory computing, hardware, software, data, and storage.");
    private static readonly CurriculumReference ACM = new("CS2023 Computer Science Curricula", "ACM, IEEE Computer Society, and AAAI", "https://csed.acm.org/knowledge-areas/", "Computing systems, software development, networks, security, and professional context.");
    private static readonly CurriculumReference MITCpp = new("6.096 Introduction to C++ — Syllabus", "MIT OpenCourseWare, EECS", "https://ocw.mit.edu/courses/6-096-introduction-to-c-january-iap-2011/pages/syllabus/", "C++ fundamentals, arrays, strings, debugging, memory, and object-oriented programming.");
    private static readonly CurriculumReference MITEff = new("6.S096 Effective Programming in C and C++ — Syllabus", "MIT OpenCourseWare, EECS", "https://ocw.mit.edu/courses/6-s096-effective-programming-in-c-and-c-january-iap-2014/pages/syllabus/", "Compiler use, debugging, C/C++ programming practices, and later-stage programming topics.");
    private static readonly CurriculumReference MITMem = new("6.088 Introduction to C Memory Management and C++ Object-Oriented Programming", "MIT OpenCourseWare, EECS", "https://ocw.mit.edu/courses/6-088-introduction-to-c-memory-management-and-c-object-oriented-programming-january-iap-2010/", "Pointers, memory management, classes, encapsulation, and object lifetime.");
    private static readonly CurriculumReference MITRec = new("Recitation 2: Foundations of Software Engineering", "MIT OpenCourseWare; notes by Petros Komodromos, University of Cyprus", "https://ocw.mit.edu/courses/1-124j-foundations-of-software-engineering-fall-2000/pages/recitations/recitation_2/", "Arrays, functions, recursion, references, pointers, dynamic memory, and classes.");
    private static readonly CurriculumReference MITMath = new("6.042J Mathematics for Computer Science — Syllabus", "MIT OpenCourseWare, EECS and Mathematics", "https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-spring-2015/pages/syllabus/", "Logic, proof, sets, functions, induction, counting, graphs, and discrete structures.");
    private static readonly CurriculumReference ASU = new("MAT 243: Discrete Mathematical Structures", "Arizona State University, School of Mathematical and Statistical Sciences", "https://math.asu.edu/mat243", "Logic, sets, functions, number theory, combinatorics, recursion, induction, and proof.");
    private static readonly CurriculumReference CCNY = new("CSC 104: Discrete Mathematical Structures Syllabus", "The City College of New York, Grove School of Engineering", "https://www.ccny.cuny.edu/compsci/csc-104-syllabus", "Logic, sets, induction, relations, counting, recurrence, graphs, and trees.");

    public static IReadOnlyList<CurriculumCourse> Enrich(IReadOnlyList<CurriculumCourse> courses) =>
        courses.Select(course => course with
        {
            Lessons = course.Lessons.Select((lesson, index) => EnrichLesson(course.Code, index + 1, lesson)).ToList()
        }).ToList();

    private static CurriculumLesson EnrichLesson(string code, int n, CurriculumLesson lesson)
    {
        var detail = Details(code, n, lesson);
        var references = code switch
        {
            "CPE 101" => n switch { 1 or 2 or 4 => new[] { Purdue, Stanford, ACM }, 3 => new[] { Purdue, Stanford }, 5 or 6 => new[] { Purdue, ACM }, _ => new[] { Purdue, Stanford } },
            "CPE 102" => n <= 2 ? new[] { MITCpp, ACM } : new[] { MITCpp, MITEff, ACM },
            "CPE 103" => new[] { MITCpp, MITMem, MITRec },
            _ => n <= 3 ? new[] { MITMath, ASU, CCNY } : new[] { MITMath, ASU, CCNY }
        };
        return lesson with
        {
            LearningObjectives = detail.Objectives,
            StudySections = detail.Sections,
            References = references.Select(source => source with
            {
                TopicsSupported = $"{lesson.Title}: {lesson.Focus}"
            }).ToArray(),
            PracticeType = detail.Type,
            ActivityPurpose = detail.Purpose,
            Activity = detail.Task,
            ActivityTask = detail.Task,
            ActivityExpectedOutput = detail.Expected,
            ActivityOptions = detail.Options,
            CodeExample = CodeExample(code, n).Code,
            CodeExpectedResult = CodeExample(code, n).Result
        };
    }

    private sealed record Guide(string[] Objectives, CurriculumSection[] Sections,
        ActivityResponseType Type, string Purpose, string Expected, string Task, string Options);

    private static Guide Details(string code, int n, CurriculumLesson lesson)
    {
        // Each guide is intentionally lesson-specific: the headings, engineering
        // examples, pitfalls, and practice format follow the topic rather than a
        // generic course-wide paragraph template.
        return (code, n) switch
        {
            ("CPE 101", 1) => G(["Distinguish raw data from interpreted information.", "Describe an algorithm using precise, finite steps.", "Decompose a computing task into testable subproblems.", "Identify inputs, processing, outputs, and constraints in a system."],
                S(("From a need to a computable problem", "Computing begins with a need, not with a particular device or programming language. A useful problem statement names the user, the desired result, the information available, and constraints such as units, time, privacy, or acceptable error. For a laboratory average, the requirement must say which readings count, what happens if none were recorded, and whether the result is rounded. These details prevent a program from appearing correct while answering the wrong question. Data are recorded symbols or measurements; information is data interpreted in a context. The same number, 24, might mean degrees Celsius, volts, or a student count, so labels and units are part of meaning."),
                  ("Decomposition, abstraction, and algorithms", "Decomposition divides a large task into smaller pieces with clear responsibilities. A sensor-monitoring task can be separated into reading values, validating ranges, calculating a statistic, and displaying a result. Abstraction keeps the details required at one stage and hides irrelevant detail: an average calculation needs a list of values and a count, not the circuit-board layout of the sensor. An algorithm is a finite, ordered, unambiguous procedure. Each step should be executable and should move toward completion. A flowchart or pseudocode can expose missing branches before code exists. A good description includes the assumptions and what should happen for empty, malformed, and boundary inputs."),
                  ("Trace a small example and test it", "Suppose three valid temperatures are 22, 24, and 26 °C. The algorithm stores the readings, adds them to obtain 72 °C-readings, divides by three readings, and reports 24 °C. This result makes sense because it lies between the smallest and largest observations. A test should include a normal case, a boundary case, and an exceptional case. For example, three equal values should return that value; no readings must not trigger division by zero; and a value outside the sensor specification should be rejected or flagged according to the requirement. Testing examples is evidence about the algorithm, not a proof that every possible input is correct."),
                  ("Computational thinking in engineering", "Engineers use decomposition to assign interfaces between components and to test them independently. A display module can assume that a measurement module returns a value with a known unit and validity flag. That contract reduces hidden assumptions. Abstraction is also useful when comparing alternative solutions: first compare required behavior and constraints, then consider implementation details. A problem can be solved without a computer, but automation is useful when the procedure is repeatable, data volume is large, or timing matters. The computer follows instructions literally; it does not infer unstated intent. Therefore, precise problem definitions and deliberate tests are core engineering work, not paperwork.")),
                ActivityResponseType.ShortAnswer, "Practice decomposing a familiar engineering-computing task before coding it.", "Submit a problem statement, inputs, outputs, constraints, and a three-or-more-step decomposition. Include one test case and its expected result.", "Problem: compute the average of valid lab readings. State assumptions and explain how your test checks the result.", ""),
            ("CPE 101", 2) => G(["Describe the fetch-decode-execute role of a processor.", "Differentiate registers, main memory, and persistent storage.", "Trace data and instruction movement through a simple system.", "Explain why buses and I/O interfaces are needed."],
                S(("Functional components", "A stored-program computer keeps instructions and data in addressable memory while a processor executes instructions. The central processing unit (CPU) includes control logic, registers, and an arithmetic-logic unit (ALU). Registers are small, fast storage locations used directly during execution. The ALU performs operations such as addition and comparisons; control logic coordinates which instruction and operands are selected. Main memory (RAM) holds active instructions and data so the CPU can access them. RAM is volatile: its contents generally do not persist when power is removed. SSDs and other persistent storage retain files but are accessed through I/O controllers rather than treated as CPU registers."),
                  ("Fetch, decode, execute", "At a simplified level, the processor fetches an instruction from memory using an address, decodes its operation and operands, executes it, and records the result. A program counter identifies the next instruction address in a basic model; branches can change that address. Real processors overlap and optimize these stages, so the model is explanatory rather than a complete account of a modern CPU. When an instruction adds two values, those values may be loaded into registers, the ALU computes the sum, and a later instruction stores the result. Memory addresses and control signals matter alongside the data itself."),
                  ("Interconnection and I/O", "A bus is a conceptual group of communication paths carrying data, addresses, and control signals. A memory read needs an address and a read operation; the selected device returns data. Input devices provide observations or user actions, while output devices present results or control an external process. An interface handles differences in timing and representation between the CPU and a device. The exact implementation may use point-to-point links rather than one shared physical bus, but the logical questions remain: who sends the data, where is it addressed, and how is the transfer coordinated?"),
                  ("Trace a file through the machine", "Opening a C++ source file starts with a storage read. The operating system requests file blocks; an I/O controller transfers them into memory; the editor reads those bytes and renders characters on a display. Editing changes the in-memory copy. Saving issues writes so persistent storage receives the updated bytes. Compilation then reads source data and produces another file, and running the program loads executable instructions and data into memory. Seeing text in an editor does not prove it has been saved, and power loss can discard unsaved RAM contents. This trace helps diagnose where a failure occurs instead of calling every problem a CPU issue.")),
                ActivityResponseType.Matching, "Match concrete computer tasks to the responsible component or storage class.", "Complete all six matches and add one sentence explaining the difference between volatile and persistent storage.", "Match: instruction arithmetic; active program data; saved source file; keyboard input; operation coordination; memory address path.", string.Join('\n', new[] { "CPU/ALU|Executes instructions and arithmetic/logic", "RAM|Active working data and program", "SSD|Persistent saved files", "Input interface|Receives keyboard data", "Control unit|Coordinates instruction execution", "Address bus/path|Selects a memory or I/O location" })),
            ("CPE 101", 3) => G(["Convert between binary, decimal, and hexadecimal positional notation.", "Explain bit and byte units and fixed-width ranges.", "Represent simple text or pixel data as encoded values.", "Distinguish unsigned values from a signed two's-complement interpretation."],
                S(("Place value and base conversion", "In a base-b positional system, each digit multiplies a power of b. For example, 101101₂ equals 1·2⁵ + 0·2⁴ + 1·2³ + 1·2² + 0·2¹ + 1·2⁰ = 45₁₀. Decimal-to-binary conversion can be done by repeated division by two and reading remainders in reverse, or by selecting powers of two. Hexadecimal is compact because one hex digit corresponds exactly to four bits: 1100 1010₂ groups as C A, giving CA₁₆. A conversion should preserve leading zeros when the stated width is significant, such as in a hardware register."),
                  ("Width, range, and signed meaning", "An n-bit unsigned pattern has 2ⁿ possible values from 0 through 2ⁿ−1. Eight bits therefore represent 0 through 255. A bit pattern by itself does not say whether its interpretation is signed, unsigned, a character, a color component, or an instruction. In two's complement, an n-bit signed range is −2ⁿ⁻¹ through 2ⁿ⁻¹−1; for eight bits that is −128 through 127. The same pattern 11111111₂ represents 255 unsigned but −1 as an eight-bit two's-complement value. Arithmetic overflow occurs when a mathematical result falls outside the representable range; the stored bit pattern then cannot preserve the intended result."),
                  ("Encoding text and images", "Text is stored by mapping characters to numeric codes, then representing those codes in bits. UTF-8 uses one to four bytes per Unicode code point, so character count and byte count are not always equal. A simple grayscale pixel can be represented by an intensity value; a color image commonly stores red, green, and blue channel samples for each pixel. Resolution, channel depth, and compression affect file size and fidelity. An image file also has structure and metadata, not only a raw sequence of visible colors. Knowing the encoding is necessary to interpret bytes; random bytes do not inherently carry labels or units."),
                  ("Check conversions systematically", "For 11001010₂, the powers-of-two sum is 128+64+8+2 = 202. Grouping into nibbles gives 1100₂ = C₁₆ and 1010₂ = A₁₆, so the result is CA₁₆. Check by converting CA back: 12·16+10 = 202. The smallest unsigned width for 202 is eight bits because 2⁷−1=127 is too small and 2⁸−1=255 is sufficient. Such reverse checks catch arithmetic slips. Always state the base and width; writing “202” without a base or signedness can be ambiguous in low-level engineering work.")),
                ActivityResponseType.Calculation, "Practice positional conversion and fixed-width reasoning using a digital measurement.", "Show place values, final decimal and hexadecimal forms, and the minimum unsigned width.", "Convert 11001010₂ to decimal and hexadecimal, then state the minimum unsigned number of bits and justify it.", ""),
            ("CPE 101", 4) => G(["Distinguish system software from application software.", "Describe an operating system's resource-management role.", "Explain the compile, link, load, and run stages at an introductory level.", "Classify a defect as translation-time or execution-time."],
                S(("Software layers", "Application software helps a person perform a task; system software manages resources and provides common services. An operating system schedules processes, manages virtual memory and files, controls devices, and enforces access boundaries. Applications normally request these services through documented interfaces rather than directly controlling every device. Utilities and drivers occupy system-software roles, although exact boundaries vary. This layered arrangement improves reuse and portability: an application can use a file API without implementing the storage controller protocol itself."),
                  ("From source to running program", "A compiler translates source code into an intermediate or machine-oriented representation and reports problems it can detect during translation. A linker combines object files and libraries and resolves references between them. A loader prepares an executable for execution, mapping required code and data into the process. Some language implementations use interpreters or just-in-time compilation, so not every system follows one identical pipeline. The important distinction is between source-level translation and the later execution of a program. A missing declaration is normally a compile-time diagnostic; an invalid file path may appear only when the running program requests the file."),
                  ("Classify and investigate failures", "A syntax error prevents the compiler from recognizing a valid program. A type error indicates incompatible operations or values. A linker error means a required symbol or library was not resolved. A runtime error occurs after execution starts, such as an invalid array index or failed file operation; a logic error may run successfully but produce the wrong answer. Read the first relevant diagnostic, note its source location, and reduce the example to the smallest case that reproduces the fault. Changing code without a hypothesis can hide the original defect."),
                  ("Example: a declared-name failure", "Consider `int total = count + 1;` when no `count` has been declared in scope. A C++ compiler can reject the name before a program runs; restarting the application or changing operating-system settings will not repair it. Declare or correct the intended value, rebuild, then test the behavior with inputs that exercise the requirement. Conversely, a program can compile while failing to open a missing runtime file. In that case, check the working directory, path, permissions, and stream status. Correct classification saves time and produces reproducible fixes.")),
                ActivityResponseType.Identification, "Classify software components and failure stages using evidence from a short scenario.", "For each item identify the responsible layer or failure stage and give a one-sentence reason.", "Classify: compiler rejects an undeclared variable; OS opens a file; spreadsheet calculates a total; compiled program cannot find a runtime input file.", ""),
            ("CPE 101", 5) => G(["Differentiate a local network, the Internet, and a web application.", "Explain IP addressing, DNS, client/server roles, and protocols.", "Trace an HTTPS request from browser to service at a high level.", "Separate name-resolution, transport, and application failures."],
                S(("Networks and layered communication", "A network connects computing devices so they can exchange data. The Internet is a network of interconnected networks that forward packets using shared protocols; it is not one central computer. A local network may connect devices in a laboratory, while routers connect it to other networks. Layering divides communication responsibilities: link technologies move frames on a local segment, IP addresses and routes packets, transport protocols provide process-to-process communication, and application protocols define messages such as web requests. This model helps isolate faults without implying that every implementation uses precisely the same components."),
                  ("Names, addresses, and services", "An IP address identifies a network interface or destination for packet delivery. People use domain names because they are easier to remember. DNS resolves names into records that help a client locate a service; a DNS answer can be cached and can change over time. DNS does not itself deliver the web page. In a client/server exchange, a browser is the client and the deployed COLMS service acts as a server for that request. A cloud service means provider-managed computing resources reached over a network; it still has applications, storage, and operational dependencies."),
                  ("Follow a secure web request", "When a student enters a COLMS address, the device resolves the hostname, establishes a network connection, negotiates HTTPS, and sends an HTTP request. TLS protects confidentiality and integrity in transit and authenticates the server certificate for the hostname. The web application processes the route and may query its database, then returns a response. A page may fail at several points: DNS could return no usable address; a connection may time out; TLS validation may fail; or the application may return an error after the connection succeeds. A browser's “site unavailable” message alone does not identify which stage failed."),
                  ("Troubleshoot by observable layer", "First confirm the URL spelling and whether other domains resolve. Next check whether the server can be reached and whether the browser reports a TLS warning. If the response is an HTTP status such as 404 or 500, the web server responded, so the failure is at the application/request layer rather than basic name resolution. Avoid sending passwords over an untrusted link or disabling certificate checks as a shortcut. Record the time, URL path, and status code while omitting credentials; these details help administrators diagnose the correct layer.")),
                ActivityResponseType.ShortAnswer, "Practice tracing a browser request and diagnosing which network stage may have failed.", "Submit a labeled request path with one observable symptom and a safe first check at each stage.", "A browser cannot open a COLMS course. Trace DNS → connection/TLS → HTTP/application and give one distinct symptom/check per stage.", ""),
            ("CPE 101", 6) => G(["Identify assets, threats, vulnerabilities, and impacts in a student system.", "Select layered controls using least privilege and authentication.", "Distinguish prevention, detection, and recovery controls.", "Explain privacy and responsible-use considerations in a computing scenario."],
                S(("Risk and defense in layers", "A security asset is something worth protecting, such as an account, student record, or service. A threat could exploit a vulnerability and cause an impact. Risk is assessed from likelihood and consequence; a simple classroom matrix helps prioritize but is not a precise universal measurement. Controls work in layers: unique passwords and multifactor authentication reduce account takeover risk; authorization limits what an account can do; software updates reduce known vulnerabilities; monitoring can detect unusual activity; and verified backups support recovery. No single measure guarantees safety."),
                  ("Identity, access, and least privilege", "Authentication asks who or what is making a request; authorization checks whether that identity may perform the requested action. A student may read their own progress but should not be able to change another student's score. Least privilege gives each account and service only the permissions needed for its work. Strong password handling means storing salted password hashes through a well-reviewed authentication system, never readable passwords. A phishing page can imitate a genuine sign-in screen, so users should verify the domain and use trusted navigation rather than entering credentials through an unexpected message."),
                  ("Privacy and responsible decisions", "Privacy is not limited to hiding secrets. Collecting only necessary personal data, explaining its purpose, restricting access, and defining retention reduce harm if information is exposed. Engineers should consider accessibility, reliability, security, and the people affected by design decisions. A convenience feature that shares a class list publicly may disclose more than students expect. Responsible practice includes documenting assumptions, reporting vulnerabilities through approved channels, and testing changes without exposing real records."),
                  ("Response and recovery", "Prevention lowers the chance of an incident; detection helps recognize it; response limits damage; recovery restores trustworthy service. A backup is useful only if it is separate from the failure and can be restored. For a suspicious password-reset message, do not follow an uncertain link; navigate to the known service, report the message, and change a password through the legitimate path if compromise is suspected. If an account is compromised, administrators should revoke sessions or credentials, preserve logs safely, assess exposed data, and communicate through the institution's incident process.")),
                ActivityResponseType.ShortAnswer, "Apply a basic threat-and-control review to a student project service.", "Submit an asset/threat/impact/control table with one preventive, one detection, and one recovery measure.", "Analyze a project site collecting names and grades. Identify one account threat and one privacy risk; propose layered controls.", ""),

            ("CPE 102", 1) => ProgrammingGuide(lesson, MITCpp, "Specification to tested program", "An algorithm is independent of C++ syntax. Before coding, identify the input domain, output format, constraints, and what constitutes a correct result. For a Celsius converter, the formula is F = 9C/5 + 32. The requirement should say whether decimal input is allowed and how output is rounded. Pseudocode makes the steps reviewable: read C; compute F; display F with its unit. Each line should map to a well-defined program operation.", "Translation and verification", "A C++ source file is compiled, linked with required definitions, and then executed. A successful compile proves only that the compiler accepted the program; it does not prove that the formula or requirement is correct. Use test cases with known answers: C=0 gives F=32, and C=100 gives F=212. A boundary or unusual case can reveal assumptions about range and precision. Keep the expected output beside each test so results are judged consistently.", ActivityResponseType.Coding, "Build an original algorithm and C++ implementation from a small conversion specification.", "Submit pseudocode, compilable C++ source, and at least two input/expected-output checks.", "Implement kilometers-to-meters conversion. Test 0 km and 2.5 km; show expected outputs and units."),
            ("CPE 102", 2) => ProgrammingGuide(lesson, MITCpp, "Objects, types, and expressions", "A declaration associates a name and type with a value or object. Choose a type from the problem's range and precision requirements: an integer count is different from a measured voltage that may include fractions. C++ arithmetic follows operand types. If both operands of 13/2 are integers, the result is 6; assigning that result to `double` afterward does not recover the discarded half. Write `13.0 / 2.0` or convert an operand before division when a fractional result is needed.", "Console input and output", "The extraction operator `>>` reads formatted values from `std::cin`; `std::cout` writes a result. Check the stream state after input because a user can enter text where a number is expected. Validate domain constraints before applying calculations. For total cost, read quantity and price, reject negative values, multiply, and format the result to two decimal places with `<iomanip>`. Variable names should communicate meaning and unit; `voltageV` is safer than an unexplained `x` in a longer calculation.", ActivityResponseType.Coding, "Use typed input, arithmetic, validation, and formatted output in a small C++ program.", "Submit code, one valid input/output example, and one invalid-input behavior.", "Read a nonnegative quantity and unit price; print total with two decimal places. Explain the chosen numeric types."),
            ("CPE 102", 3) => ProgrammingGuide(lesson, MITCpp, "Boolean expressions", "Relational operators such as `<`, `>=`, and `==` compare values and produce a Boolean result. Combine conditions with `&&` for AND and `||` for OR; apply `!` for NOT. Parentheses clarify intended grouping. A score rule “at least 70” means `score >= 70`, which includes 70. A rule requiring a value between 0 and 100 inclusive is `score >= 0 && score <= 100`. Using `||` instead would accept almost every value because a number cannot be both below zero and above 100 at once.", "Selection and boundary tests", "An `if`/`else if` chain is useful for ranges that must be mutually exclusive. Order conditions carefully, from narrow or higher-priority cases to broader cases, so an earlier branch does not capture values intended for a later branch. `switch` is appropriate for selecting among discrete integral or enumeration values, such as menu choices; it is not a substitute for arbitrary numeric ranges. Always include a default/error path. Test values just below, exactly at, and just above each threshold.", ActivityResponseType.Coding, "Implement a menu choice using selection and explicit invalid-input handling.", "Submit compilable code, outputs for two valid menu options, and one unsupported option.", "Create a C++ menu converter with two choices and a `default` path. Include tests for choices 1, 2, and 9."),
            ("CPE 102", 4) => ProgrammingGuide(lesson, MITCpp, "Loop state and invariants", "A loop has initialization, a condition, a body, and an update or other progress mechanism. The loop condition is tested before each `while` iteration; `do-while` tests after the body, so it runs at least once; `for` groups the common counter pattern. A useful loop invariant describes what is true before each iteration. For a running sum from 1 through i−1, the accumulator should equal the sum of values already processed. This lets us reason about correctness, not just syntax.", "Termination and tracing", "For a counter loop, establish a starting value, a bound, and an update that moves toward that bound. For a sentinel loop, read the first value before testing and do not include the sentinel in the data total. Trace a table of counter, condition, accumulator, and output for a small input. Test zero items, one item, and several items. An infinite loop commonly comes from an update that is missing or changes the counter in the wrong direction; an off-by-one defect often comes from `<` versus `<=`.", ActivityResponseType.Coding, "Implement sentinel-controlled collection of readings without counting the sentinel.", "Submit code and a trace table for a short input sequence, including final count and average.", "Read positive readings until -1; for 10, 20, -1 show each update and the final average. Do not include -1."),
            ("CPE 102", 5) => ProgrammingGuide(lesson, MITCpp, "Function contracts and calls", "A function separates one responsibility behind a contract. Its parameter list states required inputs; its return type states the result. A call evaluates arguments and transfers control to the function; on return, the caller resumes with the returned value. Use a `void` function when the operation reports through output or changes a passed object intentionally, and a value-returning function when a calculation produces a result. Passing by value makes a copy; a `const` reference can avoid copying a larger object while promising not to modify it.", "Scope, decomposition, and tests", "Local variables exist within their scope and should not be confused with similarly named values elsewhere. Keep functions small enough to explain and test. For rectangle area, `double area(double length, double width)` should return a product only after inputs satisfy the stated domain. Unit-aware names and contracts help avoid returning a perimeter or mixing meters with centimeters. Test a normal case, a zero dimension, and the invalid case required by the specification. Function decomposition supports reuse but does not justify splitting a simple calculation into meaningless fragments.", ActivityResponseType.Coding, "Extract a reusable calculation into a function with an explicit contract.", "Submit function code, its precondition/return meaning, and at least three tests.", "Write `powerWatts(voltage, current)` returning V×I. Test 5 V/2 A and 0 V/2 A; state the units."),
            ("CPE 102", 6) => ProgrammingGuide(lesson, MITCpp, "Array representation and bounds", "A built-in C++ array stores a fixed number of same-typed elements, and an index selects a position. With `int values[3]`, valid indexes are 0, 1, and 2; C++ does not automatically check that an index is valid. A `std::array` keeps its size as part of its type and provides `.size()`, while `std::vector` is used when size must vary. Choose a collection based on the requirement and use a loop bound that comes from the actual collection size rather than a duplicated magic number.", "Traversal, search, and debugging", "Initialize an extremum from the first valid element rather than assuming zero; all-negative data would make a zero-initialized maximum incorrect. To compute a mean, accumulate every element and divide by the number of elements using floating-point arithmetic. A linear search checks each element until a match or the end. Debug systematically: reproduce the issue with a minimal input, inspect indexes and state at each iteration, compare actual output with expected output, and change one cause at a time. A one-element array is a valuable bounds test.", ActivityResponseType.Coding, "Process a fixed set of sensor readings safely and validate outputs with targeted tests.", "Submit code, a short index trace, minimum/mean results, and a test for repeated values.", "Read five temperatures into `std::array`; report min and mean. Explain the valid index range and test all equal values."),

            ("CPE 103", 1) => ProgrammingGuide(lesson, MITCpp, "Rows, columns, and memory layout", "A two-dimensional array represents a rectangular table, but each access requires two independent indexes. For an R-by-C table, row indexes range from 0 to R−1 and columns from 0 to C−1. Nested loops should reflect this structure: the outer loop selects a row and the inner loop visits that row's columns. C++ stores built-in multidimensional arrays in row-major order, so adjacent columns of a row are contiguous. This may matter for cache locality, but correctness first depends on using the right dimensions.", "Text is data with encoding", "`std::string` provides length-aware text operations and is safer for ordinary text processing than manually managed null-terminated character arrays. A string's length in bytes can differ from its number of human-perceived characters when Unicode encoding is used. Do not assume each character occupies one byte. For sensor tables, calculate a per-row statistic by resetting row-specific accumulators inside the outer loop. Validate dimensions and reject incomplete input rather than silently treating missing readings as zero.", ActivityResponseType.Coding, "Use a table to summarize readings independently for each sensor.", "Submit code and per-sensor averages, plus the row/column range for every array access.", "Store 3 sensors × 4 samples, print each average, and identify one boundary test."),
            ("CPE 103", 2) => ProgrammingGuide(lesson, MITMem, "Address, pointer, and reference", "An object's address identifies its storage location; a pointer stores such an address and `*p` accesses the pointed-to object. A reference is an alias bound at initialization and cannot be reseated like a pointer. These mechanisms enable functions to work with caller-owned objects and are foundational to data structures, but they also introduce lifetime hazards. A pointer can be null, uninitialized, dangling, or point to an object of an unexpected lifetime. Dereference only after establishing the pointer's validity and ownership conditions.", "Dynamic lifetime and ownership", "Dynamic allocation extends object lifetime beyond a local scope, but every allocated resource needs an owner and a release path. Prefer standard-library containers and smart pointers over manual `new`/`delete` in modern C++. `std::vector<T>` manages an array's storage; `std::unique_ptr<T>` expresses unique ownership; `std::shared_ptr<T>` should be used only when shared lifetime is genuinely required. A raw pointer often works as a non-owning observer. Returning early from a function must not bypass cleanup; RAII objects handle this by releasing resources when they leave scope.", ActivityResponseType.Coding, "Inspect and improve a small memory-handling example with explicit lifetime reasoning.", "Submit corrected code or pseudocode and label each pointer as owner or non-owning observer.", "Explain why dereferencing a null/dangling pointer is invalid; propose `std::vector` for n readings and explain ownership."),
            ("CPE 103", 3) => ProgrammingGuide(lesson, MITCpp, "Model a record coherently", "A structure groups fields that describe one entity, such as a component reference, nominal value, tolerance, and unit. Grouping prevents parallel arrays from becoming misaligned when one record is inserted or removed. Use an enumeration for a fixed set of named states, such as component kind, rather than unexplained numeric codes. Define valid field ranges and initialize every record before reading it. A model should capture domain meaning: a voltage value paired with a unit is more useful than a bare floating-point number.", "Operations over structured data", "Pass a small record by value when copying is appropriate, or by `const` reference for read-only access to a larger record. Mutating functions should make their effect clear. Store records in a `std::vector<Component>` so the collection can grow. Before computing or formatting, validate that units and values are supported. A printed bill of materials should have stable column labels and precision; display formatting is separate from the numeric value kept for calculations. This separation avoids rounding the stored value merely to make the output look tidy.", ActivityResponseType.Coding, "Create a compact component inventory using a record type and named categories.", "Submit type definitions, three initialized records, and formatted output with units.", "Define a Component record with reference, value, unit, and enum kind; show three valid examples."),
            ("CPE 103", 4) => ProgrammingGuide(lesson, MITMem, "Class invariants and interface", "A class combines representation and operations. Encapsulation makes fields private so callers cannot bypass rules. An invariant is a condition that must hold before and after each public operation; for a resistor, resistance must remain positive. Constructors establish valid initial state, and methods should preserve that state or reject an invalid request. An interface describes what clients may ask the object to do without exposing how it stores data. This allows implementation changes while preserving callers' expectations.", "Design, constness, and testing", "Methods that do not change state should be marked `const`; getters should not provide writable access to private representation unless that is explicitly required. Avoid classes that merely group unrelated values with no behavior, and avoid making every field public. A `Resistor` can expose resistance and calculate current from a supplied voltage using I=V/R, after its constructor validates R>0. Tests should include a valid construction, a rejected zero or negative resistance, and calculations whose units are understood. Error behavior should be consistent with the application's design, such as an exception or explicit result type.", ActivityResponseType.Coding, "Design a small class whose public methods preserve an engineering invariant.", "Submit class code or UML-like interface, the invariant, and valid/invalid tests.", "Design `Resistor` with private resistance and `current(voltage)`. Reject R≤0 and demonstrate one result."),
            ("CPE 103", 5) => ProgrammingGuide(lesson, MITRec, "Base case and recursive reduction", "A recursive solution defines a base case that can be answered directly and a recursive case that reduces the original problem. For n≥0, factorial has 0!=1 and n!=n·(n−1)! for n>0. The input domain matters: the mathematical definition is for nonnegative integers, so a program must reject negative input rather than recurse indefinitely. Each call keeps its parameters and local state until its child call returns; this is the call stack. Recursion is a reasoning technique, not automatically faster or clearer than iteration.", "Prove progress and control resource use", "To argue termination, choose a nonnegative measure such as n that strictly decreases on every recursive call and eventually reaches zero. Trace n=4: factorial(4) waits for 4·factorial(3), which waits for 3·factorial(2), then factorial(1), then factorial(0)=1; unwinding yields 24. A missing base case or unchanged argument leads to unbounded calls and stack exhaustion. Deep recursion may use more memory than an iterative loop. Compare both approaches on a bounded range and avoid overflow in the chosen integer type.", ActivityResponseType.Coding, "Compare an iterative and recursive definition while making termination explicit.", "Submit base/recursive cases, a trace for n=4, and a comparison over values 0 through 10.", "Implement factorial recursively and iteratively for 0≤n≤10; explain the base case and decreasing measure."),
            ("CPE 103", 6) => ProgrammingGuide(lesson, MITCpp, "Files and record formats", "A file stream connects a program to persistent text or binary data. A format is a contract: field order, delimiter, encoding, and rules for missing values must be known by both writer and reader. Opening a stream can fail because a path is wrong, permissions deny access, or the device is unavailable. Check the stream before processing. Parsing should validate each field and report which record is malformed; converting an invalid line to zero can create plausible but false engineering results.", "Integration and repeatable verification", "Keep file parsing, validation, calculation, and presentation as separate functions so each can be tested. Ensure a write is checked and that the output format can be read again. Test a valid file, an empty file, a missing file, and malformed data. For a small component inventory, write one record per line with a defined delimiter, then parse each field and validate numeric range and unit. A regression test preserves behavior when one part is changed. Do not catch every exception and continue as though the input were valid; choose and document a safe error path.", ActivityResponseType.Coding, "Build a file-backed component inventory and demonstrate failure handling.", "Submit the record format, code/pseudocode, and outcomes for valid/missing/malformed files.", "Save and reload component records. Demonstrate a valid input, missing file, and malformed numeric field."),

            ("CPE 104", 1) => MathGuide(lesson, MITMath, "Propositions and operators", "A proposition is a declarative statement with a truth value. Compound statements are built with connectives: ¬p is negation, p∧q is conjunction, p∨q is inclusive disjunction, and p→q is implication. The implication is false only when its antecedent is true and its consequent is false. This truth-table definition is counterintuitive when ordinary language suggests causation, so translate each statement into named propositions before evaluating it. Parentheses encode the intended grouping of a formula.", "Truth tables and equivalence", "For n distinct proposition variables, a full truth table has 2ⁿ rows. List every valuation systematically, then evaluate subexpressions from the innermost parentheses outward. Two formulas are logically equivalent when their final columns agree for every row. For example, p→q is equivalent to ¬p∨q. A tautology is true in every row; a contradiction is false in every row. Truth tables are finite and mechanical, making them useful for checking a small digital-control condition before implementing it with logic gates or branches.", ActivityResponseType.Calculation, "Construct and evaluate a truth table for a three-variable condition.", "Submit all eight valuations, intermediate columns, and the true rows.", "Evaluate (p∧q)∨¬r for all truth assignments; clearly show intermediate columns."),
            ("CPE 104", 2) => MathGuide(lesson, ASU, "Membership and set operations", "A set is a well-defined collection of distinct elements; duplicates do not change it. Membership uses x∈A, and A⊆B means every member of A is also in B. Union collects elements in either set, intersection collects shared elements, and complement depends on a stated universal set. For A={1,2,3} and B={3,4}, A∪B={1,2,3,4} and A∩B={3}. Explicitly list or label the universe before taking a complement; otherwise “not in A” has no fixed boundary.", "Products, cardinality, and modeling", "The Cartesian product A×B consists of ordered pairs (a,b), so generally A×B differs from B×A. If |A|=m and |B|=n for finite sets, |A×B|=mn. Inclusion-exclusion gives |A∪B|=|A|+|B|−|A∩B|. It avoids counting shared students twice when enrollment sets are combined. A Venn diagram is a visual aid, but the set definitions determine the answer. In software, sets model permissions, tags, or enrolled groups; data representation must still preserve whether order or duplicates matter.", ActivityResponseType.Calculation, "Model two course-enrollment groups and calculate their set relationships.", "Submit the sets, union, intersection, symmetric difference, and cardinality check.", "Given A={a,b,c,d} and B={c,d,e}, find A∪B, A∩B, elements in exactly one set, and verify the union count."),
            ("CPE 104", 3) => MathGuide(lesson, CCNY, "Relations and representations", "A relation from A to B is a subset of A×B. It can be represented as ordered pairs, a directed graph, a matrix, or an arrow diagram. For a relation on a set A, reflexive means every (a,a) is present; symmetric means (a,b) implies (b,a); transitive means (a,b) and (b,c) imply (a,c). Check each definition separately using a counterexample search. Missing one diagonal pair disproves reflexivity; a single unmatched reverse pair disproves symmetry.", "Functions and equivalence", "A function f:A→B assigns every domain element exactly one output in B. An input with no output violates totality; an input with two distinct outputs violates uniqueness. Injective means different inputs never map to the same output; surjective means every codomain value is reached. A function has an inverse function on its image exactly when it is injective. An equivalence relation is reflexive, symmetric, and transitive; its equivalence classes partition the set into non-overlapping groups. These ideas model lookup tables, identifiers, and grouping by a shared property.", ActivityResponseType.Calculation, "Test a concrete relation for properties and decide whether it is a function/equivalence relation.", "Submit property checks with supporting pairs or counterexamples, then state the conclusion.", "On A={1,2,3}, analyze R={(1,1),(2,2),(3,3),(1,2),(2,1)} for reflexivity, symmetry, transitivity, and function status."),
            ("CPE 104", 4) => MathGuide(lesson, MITMath, "Choose a proof strategy", "A proof is a finite argument whose steps follow from definitions, assumptions, and established results. A direct proof starts from the hypothesis and derives the conclusion. A proof by contrapositive replaces P→Q with the equivalent ¬Q→¬P. Contradiction assumes the negation of the desired claim and derives an impossibility. The method should fit the statement; examples may suggest a theorem but do not prove it for an infinite domain. State domains and quantifiers carefully, because a claim about all integers differs from a claim about positive integers.", "Induction as a proof and program invariant", "Mathematical induction proves P(n) on a well-ordered sequence of integers. First prove the base case. Then assume P(k) for an arbitrary permitted k and derive P(k+1); the assumption is temporary and must be used explicitly. For the sum of the first n odd numbers, assume 1+3+…+(2k−1)=k²; adding the next odd number gives k²+(2k+1)=(k+1)². Therefore the claim holds for all positive n. Induction mirrors reasoning about loops: establish a starting state and show each iteration preserves a property, while separately showing termination.", ActivityResponseType.Calculation, "Write an induction proof with explicit base case, hypothesis, and step.", "Submit a proof with each component labeled; algebraic transformations must be shown.", "Prove 1+3+…+(2n−1)=n² for n≥1 by induction. Do not skip the k-to-k+1 algebra."),
            ("CPE 104", 5) => MathGuide(lesson, MITMath, "Product and sum rules", "The product rule applies when a construction consists of successive choices: if one stage has m options and the next has n options for every first choice, there are mn outcomes. The sum rule applies to disjoint alternatives and adds their counts. Check whether alternatives overlap before adding. For ordered selections of r distinct objects from n, P(n,r)=n!/(n−r)!. For an unordered r-element group, C(n,r)=n!/[r!(n−r)!] because each group has r! internal orders that should count as one.", "Worked count: order and repetition", "For an eight-person committee of three, order does not matter: C(8,3)=8·7·6/(3·2·1)=56. If offices are chair, secretary, and treasurer, assignments matter: P(8,3)=8·7·6=336. A four-digit PIN with repetition allowed has 10⁴ possibilities. A four-person ordered relay team from ten runners without repetition has 10·9·8·7. Write what one outcome looks like before selecting a formula. These counts also help estimate search spaces and test configurations, but do not alone measure security or real-world risk.", ActivityResponseType.Calculation, "Compare a PIN search space with role assignment using two distinct counting models.", "Show assumptions, formula, substitution, and final counts.", "Calculate a four-digit PIN count with repetition and the number of chair/secretary/treasurer assignments from ten people."),
            ("CPE 104", 6) => MathGuide(lesson, MITMath, "Represent a problem as a graph", "A graph G=(V,E) consists of vertices and edges. Vertices represent entities; an edge represents a specified relationship. Decide whether connections are directed, undirected, weighted, or multiple before choosing a representation. An adjacency list stores each vertex's neighbors and uses space proportional to vertices plus edges; an adjacency matrix uses a cell for every ordered vertex pair and makes edge lookup direct. For an undirected graph, the degree sum equals 2|E| because each edge touches two endpoints.", "Paths, connectivity, and trees", "A path follows consecutive edges. A graph is connected when every pair of vertices has a path between them. A cycle returns to its starting vertex without repeating other vertices. A tree is connected and acyclic; a tree with n vertices has n−1 edges and exactly one simple path between each pair. Removing a tree edge disconnects it, while adding a new edge creates a cycle. A drawing can mislead if crossings are mistaken for vertices, so verify the explicit edge list. Trees are useful for hierarchies; network graphs can represent physical links or logical routes, which should not be conflated.", ActivityResponseType.ShortAnswer, "Model a small campus-path network and validate graph properties.", "Submit vertex/edge definitions, an adjacency list, one path, connectivity conclusion, and degree check.", "Create a graph of five locations and their walkways. State whether it is a tree and justify with edge/path evidence."),
            _ => throw new InvalidOperationException($"Missing researched Freshman study guide for {code} lesson {n}: {lesson.Title}")
        };
    }

    private static Guide ProgrammingGuide(CurriculumLesson lesson, CurriculumReference reference,
        string heading1, string content1, string heading2, string content2,
        ActivityResponseType type, string purpose, string expected, string task) =>
        G(lesson.Concepts.Take(4).Select(x => $"Explain and apply {x.Term} in a short C++ program.").ToArray(),
          S((heading1, content1), (heading2, content2),
            ("Trace before you run", $"Use this lesson's worked example as a trace exercise: {lesson.WorkedExample} Follow every intermediate value or state change, then compare your trace with the stated result: {lesson.ExampleResult} If the trace does not match, identify the earliest statement where your reasoning diverged. A successful compile only confirms that the compiler accepted the program; it does not prove the output satisfies the intended behavior. After correcting a defect, test the original case and a boundary case."),
            ("Engineering use and review", $"Apply {lesson.Focus} to the activity scenario: {purpose} State input assumptions before choosing types or operations, and make invalid input visible instead of silently accepting it. As a review check, connect each variable and function to the requirement it supports, then test one normal input and one edge case. This is how a small classroom example becomes a reliable component in a measurement, device-state, or user-facing application.")),
          type, purpose, expected, task, "");

    private static Guide MathGuide(CurriculumLesson lesson, CurriculumReference reference,
        string heading1, string content1, string heading2, string content2,
        ActivityResponseType type, string purpose, string expected, string task) =>
        G(lesson.Concepts.Take(4).Select(x => $"Define and use {x.Term} correctly.").ToArray(),
          S((heading1, content1), (heading2, content2),
            ("Worked reasoning", lesson.WorkedExample + " " + lesson.ExampleResult + " Write each intermediate line, state the domain or universe, and explain why the chosen definition or rule applies. A correct final result without a valid argument is not a complete solution. When the result is a set or truth value, check it against the original definitions; when it is a number, substitute a small case or use an independent identity to verify it."),
            ("Computing connection and common pitfalls", $"In {lesson.Title}, the central modeling choice is {lesson.Focus}. Discrete structures support program logic, data models, verification, network design, and algorithm analysis, but the definitions still control the result. Check the domain and assumptions before applying a rule; a diagram can reveal a mistake but cannot replace a proof or calculation. Re-evaluate the worked example with a small alternate input to see which parts of the reasoning remain valid.")),
          type, purpose, expected, task, "");

    private static Guide G(string[] objectives, CurriculumSection[] sections, ActivityResponseType type,
        string purpose, string expected, string task, string options = "")
    {
        if (sections.Length < 4 || objectives.Length < 4 || string.IsNullOrWhiteSpace(task))
            throw new InvalidOperationException("A Freshman study guide needs specific objectives, four sections, and an activity task.");
        return new Guide(objectives, sections, type, purpose, expected, task, options);
    }

    private static CurriculumSection[] S(params (string Heading, string Content)[] sections) =>
        sections.Select(x => new CurriculumSection(x.Heading, x.Content)).ToArray();

    private static (string Code, string Result) CodeExample(string code, int lesson) => (code, lesson) switch
    {
        ("CPE 102", 1) => ("#include <iostream>\nint main() {\n    double celsius = 25.0;\n    double fahrenheit = 9.0 * celsius / 5.0 + 32.0;\n    std::cout << fahrenheit << \" F\\n\";\n}", "77 F"),
        ("CPE 102", 2) => ("#include <iomanip>\n#include <iostream>\nint main() {\n    int quantity = 3;\n    double unitPrice = 12.50;\n    double total = quantity * unitPrice;\n    std::cout << std::fixed << std::setprecision(2) << total << '\\n';\n}", "37.50"),
        ("CPE 102", 3) => ("#include <iostream>\nint main() {\n    int score = 70;\n    if (score >= 70) std::cout << \"Pass\\n\";\n    else std::cout << \"Retry\\n\";\n}", "Pass"),
        ("CPE 102", 4) => ("#include <iostream>\nint main() {\n    int value = 4, total = 0;\n    while (value > 0) { total += value; --value; }\n    std::cout << total << '\\n';\n}", "10"),
        ("CPE 102", 5) => ("#include <iostream>\ndouble powerWatts(double volts, double amps) { return volts * amps; }\nint main() { std::cout << powerWatts(5.0, 2.0) << \" W\\n\"; }", "10 W"),
        ("CPE 102", 6) => ("#include <array>\n#include <cstddef>\n#include <iostream>\nint main() {\n    std::array<int, 3> values{4, 7, 2};\n    int total = 0;\n    for (std::size_t i = 0; i < values.size(); ++i) total += values[i];\n    std::cout << total << '\\n';\n}", "13"),
        ("CPE 103", 1) => ("#include <array>\n#include <iostream>\nint main() {\n    std::array<std::array<int, 2>, 2> a{{{1, 2}, {3, 4}}};\n    int sum = 0;\n    for (const auto& row : a) for (int value : row) sum += value;\n    std::cout << sum << '\\n';\n}", "10"),
        ("CPE 103", 2) => ("#include <iostream>\nint main() {\n    int value = 7;\n    int* pointer = &value;\n    *pointer = 9;\n    std::cout << value << '\\n';\n}", "9"),
        ("CPE 103", 3) => ("#include <iostream>\n#include <string>\nenum class Unit { Volt, Ampere };\nstruct Reading { std::string id; double value; Unit unit; };\nint main() { Reading r{\"S1\", 5.0, Unit::Volt}; std::cout << r.id << \": \" << r.value << '\\n'; }", "S1: 5"),
        ("CPE 103", 4) => ("#include <iostream>\nclass Resistor {\n    double ohms;\npublic:\n    explicit Resistor(double r) : ohms(r) {}\n    double current(double volts) const { return volts / ohms; }\n};\nint main() { Resistor r(10.0); std::cout << r.current(5.0) << \" A\\n\"; }", "0.5 A"),
        ("CPE 103", 5) => ("#include <iostream>\nint factorial(int n) {\n    if (n == 0) return 1;\n    return n * factorial(n - 1);\n}\nint main() { std::cout << factorial(4) << '\\n'; }", "24"),
        ("CPE 103", 6) => ("#include <fstream>\n#include <iostream>\nint main() {\n    std::ifstream input(\"values.txt\");\n    if (!input) { std::cout << \"Cannot open\\n\"; return 1; }\n    int value = 0, total = 0;\n    while (input >> value) total += value;\n    std::cout << total << '\\n';\n}", "For a file containing 4, 6, and 10 on separate lines: 20"),
        _ => ("", "")
    };
}
